&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0); font-size: 12pt;&quot;&gt;&lt;strong style=&quot;font-size: 12pt;&quot;&gt;$2000 SIGN ON BONUS!&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;color: #cc092f;&quot;&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;&lt;strong&gt;Sharpen Your Nursing Skills at BAYADA!&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;We want you to flourish here — learning new skills, growing with every challenge, succeeding in each assignment, and advancing in your nursing career.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt; color: rgb(204, 9, 47);&quot;&gt;&lt;strong&gt;BAYADA Offers&lt;/strong&gt;:&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt; line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;One on one patient care&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Paid Time Off (PTO)&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Weekly Pay&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Electronic charting using Statewise&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;In-depth paid training from day one&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Award-winning adult and pediatric Simulation labs&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Cases available throughout New Castle County&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Around the clock clinical support&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;$2,000 nurse referral bonuses&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt; color: rgb(204, 9, 47);&quot;&gt;&lt;span style=&quot;color: #cc092f;&quot;&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;&lt;strong&gt;What&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;strong style=&quot;color: rgb(204, 9, 47); font-size: 12pt;&quot;&gt;&amp;nbsp;Sets BAYADA Apart:&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
